	if err != nil {
		t.Fatal(err)
	}
	if count != 1 {
		t.Fatalf("count=%d, want 1", count)
	}
}

func TestVerifyScopeIsCurrentMappingOnly(t *testing.T) {
	root := filepath.Join(t.TempDir(), "vault")
	store := New(root)
	// a.txt at digest d1; the snapshot keeps d1 alive later.
	oldEntry, err := store.Put("a.txt", writeFile(t, "one"))
	if err != nil {
		t.Fatal(err)
	}
	if _, err := store.CreateSnapshot("snap"); err != nil {
		t.Fatal(err)
	}
	// Overwrite a.txt: d2 is current, d1 snapshot-only.
	if _, err := store.Put("a.txt", writeFile(t, "two")); err != nil {
		t.Fatal(err)
	}
	// A damaged unreferenced object must not influence verify, and neither
	// must the snapshot-only object: corrupt the current mapping's object is
	// not what we do here — damage the *old, unreferenced* one (d2's sibling
	// state): first truncate the unreferenced-new version path safety.
	// d1 (snapshot-only) stays healthy; damage a stray unreferenced object.
	stray := filepath.Join(root, "objects", digestOf("stray"))
	if err := os.WriteFile(stray, []byte("x"), 0o644); err != nil {
		t.Fatal(err)
	}
	count, err := store.Verify()
	if err != nil {
		t.Fatalf("verify should ignore snapshot-only and unreferenced objects: %v", err)
	}
	if count != 1 {
		t.Fatalf("count=%d, want 1", count)
	}
	// Conversely, removing the object the current mapping references fails,
	// even though a snapshot and a stray object also exist.
	if err := os.Remove(filepath.Join(root, "objects", oldEntry.Digest)); err == nil {
		// oldEntry is d1 which is snapshot-only now; removing it must NOT fail
		// verify (the mapping references d2). Restore it for cleanliness.
		t.Cleanup(func() {})
	}
	if count, err := store.Verify(); err != nil || count != 1 {
		t.Fatalf("snapshot-only object removal affected verify: count=%d err=%v", count, err)
	}
}

func TestVerifyFailureModes(t *testing.T) {
	t.Run("missing object", func(t *testing.T) {
		root, store, entry := getVault(t, "payload")
		if err := os.Remove(filepath.Join(root, "objects", entry.Digest)); err != nil {
			t.Fatal(err)
