		// Same length, different bytes: checksum error must win.
		if err := os.WriteFile(filepath.Join(root, "objects", entry.Digest), []byte("XXXXXXX"), 0o644); err != nil {
			t.Fatal(err)
		}
		err := expectVerifyFailure(t, store)
